import{_ as a,o as e,c as n,a0 as o}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"分组","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/RegExp/5-group.md","filePath":"jsApi/RegExp/5-group.md","lastUpdated":1791573371000}'),p={name:"jsApi/RegExp/5-group.md"};function l(r,s,c,t,i,d){return e(),n("div",null,[...s[0]||(s[0]=[o('<h1 id="分组" tabindex="-1">分组 <a class="header-anchor" href="#分组" aria-label="Permalink to &quot;分组&quot;">​</a></h1><h2 id="_1-分组" tabindex="-1">1 分组 <a class="header-anchor" href="#_1-分组" aria-label="Permalink to &quot;1 分组&quot;">​</a></h2><p>如果我们像匹配一个单词多次，比如 <code>byron</code></p><p>如果这么写 <code>\\byron{3}\\g</code>，只能匹配末尾的 <code>n</code> 3 次，不能匹配整个单词</p><p>需要匹配整个单词需要使用分组</p><blockquote><p>使用 <code>()</code> 表示分组，使量词作用于分组</p></blockquote><p>实现上面的功能就可以这么写 <code>\\(byron){3}\\g</code></p><h3 id="_1-1-例子" tabindex="-1">1.1 例子 <a class="header-anchor" href="#_1-1-例子" aria-label="Permalink to &quot;1.1 例子&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">&#39;a1b3c3def&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">replace</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/(</span><span style="color:#005CC5;">[a-z]\\d</span><span style="color:#032F62;">)</span><span style="color:#D73A49;">{3}</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">g</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;X&#39;</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// Xdef</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_2-或" tabindex="-1">2 或 <a class="header-anchor" href="#_2-或" aria-label="Permalink to &quot;2 或&quot;">​</a></h2><p>将 a1b 或 a2b 替换成 X</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">&#39;a1b a2b a3b abc&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">replace</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/a(1</span><span style="color:#D73A49;">|</span><span style="color:#032F62;">2)b/</span><span style="color:#D73A49;">g</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;X&#39;</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// X X a3b abc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_3-捕获分组" tabindex="-1">3 捕获分组 <a class="header-anchor" href="#_3-捕获分组" aria-label="Permalink to &quot;3 捕获分组&quot;">​</a></h2><p>分组之后可以捕获分组，也就是拿到分组匹配到的值，比如下面的场景：</p><p>将 <code>2015-12-25</code> 转换成 <code>25/12/2015</code></p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">&#39;2015-12-25&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">replace</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{4}</span><span style="color:#032F62;">)-(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)-(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)/</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;$3/$2/$1&#39;</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// 25/12/2015</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_4-忽略分组" tabindex="-1">4 忽略分组 <a class="header-anchor" href="#_4-忽略分组" aria-label="Permalink to &quot;4 忽略分组&quot;">​</a></h2><p>(:?xxx) <code>:?</code> 忽略分组</p><p>假如有场景有分组，但是不想记住分组，如上面的例子，忽略年份</p><p>将 <code>2015-12-25</code> 转换成 <code>25/12/2015</code></p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">&#39;2015-12-25&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">replace</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/(:</span><span style="color:#D73A49;">?</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{4}</span><span style="color:#032F62;">)-(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)-(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)/</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;$2/$1&#39;</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// 25/12</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',21)])])}const u=a(p,[["render",l]]);export{b as __pageData,u as default};
